/* ===== PORTADA AUTOMÁTICA: se arma sola con las notas más nuevas de contenido/notas.json.
   "peso": 3 manda una nota a principal (si está entre las 6 más nuevas); "peso": 2 la pone en Esenciales.
   "minuto": ["frase en español","English line"] la pone en Hoy en un minuto. ===== */
const ORD=l=>l.slice().sort((a,b)=>((b.date||"")+(b.hora||"")).localeCompare((a.date||"")+(a.hora||""))||A.indexOf(a)-A.indexOf(b));
const HOME=(()=>{
  const S=ORD(A);
  const lead=((S.slice(0,6).find(a=>(a.peso||0)>=3))||S[0]||{}).id;
  const rest=S.filter(a=>a.id!==lead);
  const first=k=>(S.find(a=>a.sec===k)||{}).id;
  const picks=S.slice(0,60).filter(a=>(a.peso||0)>=2).map(a=>a.id);
  for(const a of S){if(picks.length>=5)break;if(!picks.includes(a.id))picks.push(a.id)}
  const cnt={};S.slice(0,40).forEach(a=>cnt[a.tag]=(cnt[a.tag]||0)+1);
  return {lead,ess:rest.slice(0,4).map(a=>a.id),row:rest.slice(4,8).map(a=>a.id),
    duo:[first("artistas"),first("critica")||first("industria")].filter(Boolean),
    picks:picks.slice(0,5),trend:Object.keys(cnt).sort((x,y)=>cnt[y]-cnt[x]).slice(0,8),
    min:S.filter(a=>a.minuto).slice(0,5).map(a=>[a.id,a.minuto[0],a.minuto[1]])};
})();
